@classmethod
def make_compound_path(cls, *args):
    """Make a compound path from a list of Path objects."""
    # Handle an empty list in args (i.e. no args).
    if not args:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = []
    codes = []
    for path in args:
        if path.vertices.size > 0:
            if vertices:
                vertices.append(path.vertices[0])
                codes.append(cls.MOVETO)
            vertices.extend(path.vertices[1:])
            codes.extend(path.codes[1:])
        else:
            continue

    if not vertices:
        return Path(np.empty([0, 2], dtype=np.float32))

    vertices = np.concatenate([v[np.newaxis] for v in vertices])
    codes = np.array(codes, dtype=cls.code_type)

    # Change the last STOP to LINETO if it exists
    if codes[-1] == cls.STOP:
        codes[-1] = cls.LINETO

    return cls(vertices, codes)
